CREATE TABLE "CustomerAddress" ("id" UUID PRIMARY KEY,"customerId" UUID NOT NULL REFERENCES "Customer"("id") ON DELETE RESTRICT,"label" TEXT NOT NULL DEFAULT '',"text" TEXT NOT NULL,"latitude" DOUBLE PRECISION CHECK ("latitude" BETWEEN -90 AND 90),"longitude" DOUBLE PRECISION CHECK ("longitude" BETWEEN -180 AND 180),"version" INTEGER NOT NULL DEFAULT 1 CHECK ("version">0),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (("latitude" IS NULL)=("longitude" IS NULL)));
CREATE INDEX "CustomerAddress_customerId_createdAt_idx" ON "CustomerAddress"("customerId","createdAt");
